const tabId = 118779795;
const pageInfo = await browserjs(tabId, () => {
  const paginationText = document.querySelector('.pagination, app-pagination, .mat-paginator')?.textContent || 
                         Array.from(document.querySelectorAll('*')).find(el => el.textContent.includes('125 results'))?.parentElement?.textContent;

  const allRows = Array.from(document.querySelectorAll('table tbody tr')).map(r => {
