    const distNum = parseFloat(distText);
    return {
      name: cells[0]?.textContent?.trim(),
      info: cells[1]?.textContent?.trim(),
      distanceStr: distText,
      distanceNum: isNaN(distNum) ? null : distNum
    };
  });

  return {
    paginationText: paginationText?.trim().replace(/\s+/g, ' '),
    totalRowsRendered: allRows.length,
    minDistance: Math.min(...allRows.map(r => r.distanceNum).filter(n => n !== null)),
    sortedDistances: [...new Set(allRows.map(r => r.distanceNum))].sort((a,b) => a - b),
    firstRow: allRows[0]
  };
});
